def verify_requirements():
    """Verify all requirements from issue description are met."""
    print("\n=== Verifying all requirements ===")

    multidict_code = open('aiohttp/multidict.py').read()
    namespace = {}
    exec(multidict_code, namespace)
    MultiDict = namespace['MultiDict']

    requirements_met = []

    # Requirement 1: Constructor should reject more than 1 positional argument
    try:
        MultiDict(('k1', 'v1'), ('k2', 'v2'))
        requirements_met.append(("Rejects >1 args", False, "Should have rejected"))
    except TypeError:
        requirements_met.append(("Rejects >1 args", True, "Correctly rejects"))

    # Requirement 2: Error message should state "at most 1 positional argument"
    try:
        MultiDict(('k1', 'v1'), ('k2', 'v2'))
    except TypeError as e:
        msg = str(e)
        if "at most 1 positional argument" in msg:
            requirements_met.append(("'at most 1' in message", True, "Correct text"))
        else:
            requirements_met.append(("'at most 1' in message", False, f"Got: {msg}"))

    # Requirement 3: Error message should accurately report number given
    try:
        MultiDict(('k1', 'v1'), ('k2', 'v2'))  # 2 args
    except TypeError as e:
        msg = str(e)
        if "(2 given)" in msg:
            requirements_met.append(("Accurate count (2)", True, "Reports 2 given"))
        else:
            requirements_met.append(("Accurate count (2)", False, f"Wrong count in: {msg}"))

    try:
        MultiDict(('k1', 'v1'), ('k2', 'v2'), ('k3', 'v3'))  # 3 args  
    except TypeError as e:
        msg = str(e)
        if "(3 given)" in msg:
            requirements_met.append(("Accurate count (3)", True, "Reports 3 given"))
        else:
            requirements_met.append(("Accurate count (3)", False, f"Wrong count in: {msg}"))

    # Print results
    all_passed = True
    for req, passed, detail in requirements_met:
        status = "✅" if passed else "❌"
        print(f"{status} {req}: {detail}")
        if not passed:
            all_passed = False

    return all_passed

